import { DateTime } from 'luxon'
import { BaseModel, belongsTo, column } from '@adonisjs/lucid/orm'
import type { BelongsTo } from '@adonisjs/lucid/types/relations'
import Supplier from '#models/supplier'

export type ApprovalStep = {
  approvedByName: string
  approvedAt: string
}

export default class Invoice extends BaseModel {
  @column({ isPrimary: true })
  declare id: number

  @column()
  declare organisationId: number

  @column()
  declare supplierId: number

  @column()
  declare reference: string

  @column()
  declare grossCents: number

  @column()
  declare currency: string

  /**
   * The account the payment run will credit. Treated as payment instruction
   * data, not as reference data, so it is only ever shown to the tenant that
   * owns the invoice.
   */
  @column()
  declare bankAccountIban: string

  @column()
  declare status: 'draft' | 'awaiting_approval' | 'approved' | 'paid'

  @column.date()
  declare dueOn: DateTime

  @column({
    prepare: (value: ApprovalStep[]) => JSON.stringify(value ?? []),
  })
  declare approvalTrail: ApprovalStep[]

  @belongsTo(() => Supplier)
  declare supplier: BelongsTo<typeof Supplier>
}

