import db from '@adonisjs/lucid/services/db'

export type SettlementInstruction = {
  organisationId: number
  instructionReference: string
  settledCents: number
  valueDate: string
}

/**
 * Marks a payment instruction, and every invoice behind it, as settled.
 * Authenticating the settlement source is the caller's job: by the time a
 * payload reaches here it is treated as the bank's own word.
 */
export async function applySettlement(instruction: SettlementInstruction) {
  return db.transaction(async (trx) => {
    const row = await trx
      .from('payment_instructions')
      .where('reference', instruction.instructionReference)
      .andWhere('organisation_id', instruction.organisationId)
      .first()

    if (!row) {
      throw new Error(`E_UNKNOWN_INSTRUCTION: ${instruction.instructionReference}`)
    }

    await trx.from('payment_instructions').where('id', row.id).update({
      status: 'settled',
      settled_cents: instruction.settledCents,
      value_date: instruction.valueDate,
    })

    await trx.from('invoices').where('payment_instruction_id', row.id).update({ status: 'paid' })

    return { instructionReference: instruction.instructionReference, status: 'settled' as const }
  })
}

